head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF31201";
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31201' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31201' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31201.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onclick = function(e){
    try {
        IsurcdSearch2('ISU_CD','COM_NM',315,155)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31201.img_70_onclick' }); }
};

/**
 * @method
 * @name img_70_onmouseover
 * @description img_70 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31201.img_70_onmouseover' }); }
};

/**
 * @method
 * @name btn_Reset_onclick
 * @description btn_Reset 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Reset_onclick = async function(e){
    try {
        await scwin.reset()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31201.btn_Reset_onclick' }); }
};

/**
 * @method
 * @name btn_Cal2_onclick
 * @description btn_Cal2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cal2_onclick = async function(e){
    try {
        await scwin.cal2()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31201.btn_Cal2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Cal2
 * @description Cal2 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal2 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal2"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal2", unresolved: "action:self_submit:tx_fn_Cal2" };
};

/**
 * @method
 * @name tx_fn_ExcelDown
 * @description Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExcelDown = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_ExcelDownReq") ? $c.util.getComponent("dma_ExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reset = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    $c.util.getComponent("cal_decisionDate").setValue("");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    const p = {}; p["ISU_CD"] = $c.util.getComponent("dma_Cal2Req").get("ISU_CD"); p["COM_NM"] = $c.util.getComponent("ipt_COM_NM_2").getValue(); p["SCREN_ID"] = $c.util.getComponent("dma_Cal2Req").get("SCREN_ID"); p["SCREN_PROCES_TP_CD"] = $c.util.getComponent("dma_Cal2Req").get("SCREN_PROCES_TP_CD"); p["decisionDate"] = $c.util.getComponent("cal_decisionDate").getValue(); p["gubun"] = $c.util.getComponent("ipt_gubun").getValue(); p["decisionAmount"] = $c.util.getComponent("ipt_decisionAmount").getValue(); p["decisionMoney"] = $c.util.getComponent("ipt_decisionMoney").getValue(); p["restDate"] = $c.util.getComponent("ipt_restDate").getValue(); p["cumulationAmount"] = $c.util.getComponent("ipt_cumulationAmount").getValue(); p["cumulationMoney"] = $c.util.getComponent("ipt_cumulationMoney").getValue(); p["isCompletion"] = $c.util.getComponent("ipt_isCompletion").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDSTF31201.xml', p);
};

/**
 * @method
 * @name cal2
 * @description cal2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal2 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    await scwin.tx_fn_Cal2();
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkNum = function () {
    if (event.keyCode === 8 || event.keyCode === 46) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @param {String} tableID tableID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function (tableID) {
    if (tableID.rows.length === 0) {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent('dma_Cal2Req').set('excelData', tableID.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    await scwin.tx_fn_ExcelDown();
};
